const crypto = require('crypto');
const secret = $vars.N8N_WEBHOOK_SECRET;
const timestamp = Date.now();
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.`).digest('hex');
return [{ json: { ...$('Verify Signature').first().json, timestamp, signature } }];

const text = $input.first().json.choices[0].message.content;
const withoutThoughts = text.replace(/<thought>[\s\S]*?<\/thought>/gi, '');
const cleaned = withoutThoughts.trim().replace(/^```(?:json)?\s*|\s*```$/g, '');
const parsed = JSON.parse(cleaned);
return [{ json: { leadId: $('Verify Signature').first().json.leadId, orgId: $('Verify Signature').first().json.orgId, agentId: $('GET Agent Prompt (enricher)').first().json.agent.id, ...parsed } }];

const crypto = require('crypto');
const secret = $vars.N8N_WEBHOOK_SECRET;
const timestamp = Date.now();
const body = { companySize: $json.company_size, industry: $json.industry, revenueRange: $json.revenue_range, technologiesUsed: $json.technologies_used, socialProfiles: $json.social_profiles };
